/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { CircularOrthogonalEnsembleModel, CircularSymplecticEnsembleModel, CircularUnitaryEnsembleModel, GaussianOrthogonalEnsembleModel, GaussianSymplecticEnsembleModel, GaussianUnitaryEnsembleModel, JointEigenDistribution, Matrix, MatrixSymbol, NormalDistribution, RandomMatrixPSpace, RandomMatrixSymbol, RandomSymbol, SingleContinuousPSpace, Sym, jointEigenDistribution, levelSpacingDistribution, rational, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.stats.random_matrix_models", () => {
  it("joint_eigen_distribution(C)", () => {
    const O = new Sym('O');
    expect(sympyStr(jointEigenDistribution(new RandomMatrixSymbol(O, rational(1), rational(1), new RandomMatrixPSpace([O, new CircularOrthogonalEnsembleModel([O, rational(1)])]))))).toBe('Lambda(t[1], Product(Abs(exp(I*t[_j]) - exp(I*t[_k])), (_j, _k + 1, 1), (_k, 1, 0))/(2*pi))');
  });
  it("joint_eigen_distribution(C) (2)", () => {
    const S = new Sym('S');
    expect(sympyStr(jointEigenDistribution(new RandomMatrixSymbol(S, rational(1), rational(1), new RandomMatrixPSpace([S, new CircularSymplecticEnsembleModel([S, rational(1)])]))))).toBe('Lambda(t[1], Product(Abs(exp(I*t[_j]) - exp(I*t[_k]))**4, (_j, _k + 1, 1), (_k, 1, 0))/(2*pi))');
  });
  it("joint_eigen_distribution(C) (3)", () => {
    const U = new Sym('U');
    expect(sympyStr(jointEigenDistribution(new RandomMatrixSymbol(U, rational(1), rational(1), new RandomMatrixPSpace([U, new CircularUnitaryEnsembleModel([U, rational(1)])]))))).toBe('Lambda(t[1], Product(Abs(exp(I*t[_j]) - exp(I*t[_k]))**2, (_j, _k + 1, 1), (_k, 1, 0))/(2*pi))');
  });
  it("density(G)(X)", () => {
    const U = new Sym('U');
    expect(sympyStr(new GaussianOrthogonalEnsembleModel([U, rational(2)]).call(new MatrixSymbol('X', rational(2), rational(2))))).toBe('exp(-Trace(X**2)/2)/Integral(exp(-Trace(_H**2)/2), _H)');
  });
  it("density(G)(X) (2)", () => {
    const U = new Sym('U');
    expect(sympyStr(new GaussianSymplecticEnsembleModel([U, rational(2)]).call(new MatrixSymbol('X', rational(2), rational(2))))).toBe('exp(-2*Trace(X**2))/Integral(exp(-2*Trace(_H**2)), _H)');
  });
  it("density(G)(X) (3)", () => {
    const U = new Sym('U');
    expect(sympyStr(new GaussianUnitaryEnsembleModel([U, rational(2)]).call(new MatrixSymbol('X', rational(2), rational(2))))).toBe('exp(-Trace(X**2))/(2*pi**2)');
  });
  it("JointEigenDistribution(Matrix(A))", () => {
    const [A00, A01, A10, A11] = symbols('A00 A01 A10 A11');
    expect(sympyStr(JointEigenDistribution(Matrix.of([[new RandomSymbol(A00, new SingleContinuousPSpace([A00, new NormalDistribution([rational(0), rational(1)])])), new RandomSymbol(A01, new SingleContinuousPSpace([A01, new NormalDistribution([rational(0), rational(1)])]))], [new RandomSymbol(A10, new SingleContinuousPSpace([A10, new NormalDistribution([rational(0), rational(1)])])), new RandomSymbol(A11, new SingleContinuousPSpace([A11, new NormalDistribution([rational(0), rational(1)])]))]])))).toBe('JointDistributionHandmade(-sqrt(A00**2 - 2*A00*A11 + 4*A01*A10 + A11**2)/2 + A00/2 + A11/2, sqrt(A00**2 - 2*A00*A11 + 4*A01*A10 + A11**2)/2 + A00/2 + A11/2)');
  });
  it("joint_eigen_distribution(U)", () => {
    const U = new Sym('U');
    expect(sympyStr(jointEigenDistribution(new RandomMatrixSymbol(U, rational(2), rational(2), new RandomMatrixPSpace([U, new GaussianUnitaryEnsembleModel([U, rational(2)])]))))).toBe('Lambda((l[1], l[2]), exp(-l[1]**2 - l[2]**2)*Product(Abs(l[_i] - l[_j])**2, (_j, _i + 1, 2), (_i, 1, 1))/pi)');
  });
  it("level_spacing_distribution(U)", () => {
    const U = new Sym('U');
    expect(sympyStr(levelSpacingDistribution(new RandomMatrixSymbol(U, rational(2), rational(2), new RandomMatrixPSpace([U, new GaussianUnitaryEnsembleModel([U, rational(2)])]))))).toBe('Lambda(_s, 32*_s**2*exp(-4*_s**2/pi)/pi**2)');
  });
});
